    filtrarItens: function(chk, opcao){
        var filtro = []
        if(!chk.checked == true){
            this._toolbar.activeMenuBtn.menu.items.items.forEach(function(item){
                if(item.id != opcao && item.checked == true){
                    item.setChecked(false);
                }else{
                    filtro.push(opcao);
                }
            });
        }else if(!chk.checked == false && opcao == 'todos'){
            filtro.push(opcao);

            if(opcao == 'todos'){
                this._toolbar.activeMenuBtn.menu.items.items.forEach(function(item){
                    if(item.id == 'todos'){
                        item.setChecked(true);
                    }else if(item.id != opcao){
                        item.setChecked(false);
                    }
                });
            }
        }

        var ano = 0;
        var mes = 0;
        this._toolbar.items.items.forEach(function(item, i){
            if(item.emptyText == 'Ano para filtro'){ ano = item.getValue(); }
            if(item.emptyText == 'Mês para filtro'){ mes = item.getValue(); }
        });



        this.getStore().baseParams['periodo_ano'] = ano;
        this.getStore().baseParams['periodo_mes'] = mes;
        this.getStore().baseParams['filtro'] = [...new Set(filtro)]

        if(this.getStore().lastOptions.params){
            delete this.getStore().lastOptions.params.start;
            delete this.getStore().lastOptions.params.limit;
        }

        this.getStore().load();
    },

    filtroMesAno: function(){
        var ano = 0;
        var mes = 0;
        this._toolbar.items.items.forEach(function(item, i){
            if(item.emptyText == 'Ano para filtro'){ ano = item.getValue(); }
            if(item.emptyText == 'Mês para filtro'){ mes = item.getValue(); }
        });

        this.getStore().baseParams['periodo_ano'] = ano;
        this.getStore().baseParams['periodo_mes'] = mes;
        this.getStore().load();
    },

