    doDownload: function() {
        var config = {
            filter: Ext.encode(this.getFilter()),
            keyword: this.getKeywordField().getValue(),
            start: 0,
            limit: this.getStore().getTotalCount(),
            format: 'text/csv',
            periodo_ano: this.getStore().baseParams['periodo_ano'],
            periodo_mes: this.getStore().baseParams['periodo_mes'],
            filtro: (this.getStore().baseParams['filtro'] === "" || this.getStore().baseParams['filtro'] === undefined) ? 'todos' : this.getStore().baseParams['filtro'],
        };
        var rest = this.factoryRestful();
        var url = rest.getRoute('export').url + '?' + Ext.urlEncode(config);

        window.open(url, '_self');
    },

    gerarRelatorioTeletrabalhoCompetencia: function(){

        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action('TeletrabalhoCompetenciaRelatorio', 'generate_report'),
            params: {
                periodo_ano: this.getStore().baseParams['periodo_ano'],
                periodo_mes: this.getStore().baseParams['periodo_mes'],
                filtro: (this.getStore().baseParams['filtro'] === "" || this.getStore().baseParams['filtro'] === undefined) ? 'todos' : this.getStore().baseParams['filtro'],
                busca:  (this.getStore().baseParams['keyword'] === "" || this.getStore().baseParams['keyword'] === undefined) ? '' : this.getStore().baseParams['keyword']
                
            },
            success: function (request) {
                var obj = Ext.decode(request.responseText);
                if (obj.success){
                    Ext.Msg.show({
                        title: 'Solicitando Relatório',
                        msg: obj.message,
                        icon: Ext.Msg.INFO,
                        buttons: Ext.Msg.OK
                    });
                    if (obj.download){
                        var RemoteObserver = core.RemoteObserver;
                        var cb = RemoteObserver.on('base-report', {
                            scope: this,
                            fn: function (data) {
                                setTimeout(
                                    function() {
                                        toolkit.util.downloadFile({
                                            url: data.path,
                                            filename: data.filename,
                                            approach: 'download',
                                        });;
                                        RemoteObserver.un('base-report', {scope: this})
                                        setTimeout( function() {
                                            Ext.Ajax.request({
                                                url: toolkit.util.Normalize.controller_action(
                                                    'TeletrabalhoCompetenciaRelatorio.',
                                                    'marker'
                                                ),
                                                params: {
                                                    uuid: obj.uuid
                                                },
                                                success: function() {},
                                                failure: function() {},
                                            });
                                        },
                                        2000);
                                    },
                                    1000
                                );
                            }
                        });
                    }
                }else{
                    Ext.Msg.show({
                        title: 'Error',
                        msg: obj.message,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK
                    });
                }
            },
            failure: function (request) {
                Ext.Msg.show({
                    msg: 'Ocorreu um erro tentando processar sua requisição, tente novamente mais tarde.',
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK
                })
            },
            scope: this
        });
    },


